<?php
require_once __DIR__.'/includes/panel_helpers.php';exigirRol([1]);require_once __DIR__.'/../config/database.php';
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){header('Location: pagos.php');exit;}
$pago=null;$error=null;
try{$pdo=conectarBD();$s=$pdo->prepare("SELECT pg.*,p.nombres||' '||p.apellidos paciente,c.codigo_cita FROM pagos pg JOIN pacientes p ON p.id=pg.paciente_id JOIN citas c ON c.id=pg.cita_id WHERE pg.id=:id");$s->execute(['id'=>$id]);$pago=$s->fetch();if(!$pago||$pago['estado']!=='pagado')$error='El pago no existe o ya fue anulado.';
if($_SERVER['REQUEST_METHOD']==='POST'&&!$error){$token=$_POST['csrf_token']??'';if(!is_string($token)||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(403);exit('Solicitud no válida.');}$motivo=trim((string)($_POST['motivo']??''));if($motivo===''||mb_strlen($motivo)>500)$error='Indica el motivo de la anulación.';else{$pdo->beginTransaction();$u=$pdo->prepare("UPDATE pagos SET estado='anulado',anulado_at=now(),anulado_por=:usuario,motivo_anulacion=:motivo,updated_at=now() WHERE id=:id AND estado='pagado'");$u->execute(['usuario'=>$_SESSION['usuario_id'],'motivo'=>$motivo,'id'=>$id]);if($u->rowCount()!==1)throw new RuntimeException('Pago no disponible.');$pdo->prepare("INSERT INTO historial_pagos(pago_id,usuario_id,accion,comentario) VALUES(:pago,:usuario,'anulacion',:motivo)")->execute(['pago'=>$id,'usuario'=>$_SESSION['usuario_id'],'motivo'=>$motivo]);$pdo->commit();$_SESSION['csrf_token']=bin2hex(random_bytes(32));header('Location: pagos.php?anulado=1');exit;}}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$error='No se pudo anular el pago.';}
require_once __DIR__.'/includes/layout.php';renderSidebar('pagos');?>
<div class="payment-form-shell"><div class="doctor-page-heading"><div><span class="doctor-eyebrow">Acción administrativa</span><h1>Anular pago</h1><p>Esta operación quedará registrada en el historial.</p></div><a class="btn btn-secondary" href="pagos.php">Volver</a></div><?php if($error):?><div class="alert alert-error"><?= h($error) ?></div><?php elseif($pago):?><section class="card"><div class="card-body"><div class="profile-data"><div><span>Comprobante</span><strong><?= h($pago['codigo_pago']) ?></strong></div><div><span>Paciente</span><strong><?= h($pago['paciente']) ?></strong></div><div><span>Cita</span><strong><?= h($pago['codigo_cita']) ?></strong></div><div><span>Monto</span><strong>Bs <?= number_format((float)$pago['monto'],2) ?></strong></div></div><form method="POST" class="stack"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="form-group"><label class="form-label required" for="motivo">Motivo de anulación</label><textarea class="form-textarea" id="motivo" name="motivo" maxlength="500" rows="4" required></textarea></div><button class="btn patient-cancel-button" type="submit" data-confirm="¿Confirmas la anulación de este pago?">Anular pago</button></form></div></section><?php endif;?></div><?php renderFooter();?>
